pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: give player 10 wei
        vm.deal(address(0x1), 10);
        // Warp to a block where random % 2 == 0 (block.timestamp even)
        vm.warp(1);
        vm.roll(0); // block.difficulty is 0 in the EVM, so keccak256(...)%2 == 0 when block.timestamp is even
        vm.prank(address(0x1));
        c.play{value: 10}();
        // After play, player should have received 9 wei (pot - fee) and bank 1 wei (fee), pot becomes 0
        // Player's balance after tx: 0 initial + refund 9 = 9 wei
        // Bank's balance after tx: 0 initial + 1 fee = 1 wei
        assertEq(address(0x1).balance, 9);
    }
}

